from itertools import permutations

def is_balanced(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if lst[0] == '' and lst[1] == '':
        return 'Yes'

    open_count = lst[0].count('(') + lst[1].count('(')
    close_count = lst[0].count(')') + lst[1].count(')')

    if open_count != close_count:
        return 'No'

    permutations_lst = [''.join(p) for p in permutations(lst)]

    for perm in permutations_lst:
        if is_balanced(perm):
            return 'Yes'

    return 'No'

